+
+            if (claimedCards == null || nextClaimedCards == null)
+            {
+                return false;
+            }
+
+            for (int i = 0; i < claimedCards.Length; i++)
+            {
+                if (claimedCards[i] && (i >= nextClaimedCards.Count || !nextClaimedCards[i]))
+                {
+                    return true;
+                }
+            }
+
+            return false;
+        }
